INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20501, 'អនុគមន៍ \(y=f(x)\) ជាប់ត្រង់ចំណុច \(x=c\) កាលណា ៖', NULL, '["\\(f(c)=0\\)", "\\(\\displaystyle\\lim_{x\\to c}f(x)=f(c)\\)", "\\(f''(c)\\) មាន", "\\(\\displaystyle\\lim_{x\\to c}f(x)=+\\infty\\)"]', 1, NULL, 1, 'mcq', 'និយមន័យ ៖ \(f\) កំណត់ត្រង់ \(c\) មានលីមីតកាលណា \(x\to c\) ហើយ \(\displaystyle\lim_{x\to c}f(x)=f(c)\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20502, 'អនុគមន៍ \(f(x)=3 x^{2} + x - 7\) ជាប់ចំពោះតម្លៃ \(x\) ណាខ្លះ ?', NULL, '["\\(x\\ne1\\)", "\\(x\\ne0\\)", "\\(x\\in\\mathbb{R}\\)", "\\(x>0\\)"]', 2, NULL, 1, 'mcq', '\(f\) ជាអនុគមន៍ពហុធា ដូច្នេះជាប់គ្រប់ចំនួនពិត។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20503, 'បើអនុគមន៍ \(f\) ជាប់លើ \([a,b]\) ហើយ \(f(a)<0<f(b)\) នោះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាល ៖', NULL, '["មាន \\(c\\) ដែល \\(f''(c)=0\\)", "មាន \\(c\\in(a,b)\\) ដែល \\(f(c)=0\\)", "\\(f(x)>0\\) គ្រប់ \\(x\\in[a,b]\\)", "\\(f\\) កើនដាច់ខាតលើ \\([a,b]\\)"]', 1, NULL, 1, 'mcq', 'ដោយ \(0\) នៅចន្លោះ \(f(a)\) និង \(f(b)\) ហើយ \(f\) ជាប់ ដូច្នេះមាន \(c\in(a,b)\) ដែល \(f(c)=0\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20504, 'ដើម្បីបន្ថាយ \(f(x)=\dfrac{x^2-9}{x-3}\) តាមភាពជាប់ត្រង់ \(x=3\) ត្រូវកំណត់ \(g(3)\) ស្មើនឹងលីមីត \(\lim_{x\to 3}\dfrac{x^{2} - 9}{x - 3}\)។', NULL, '["\\(0\\)", "\\(9\\)", "\\(3\\)", "\\(6\\)"]', 3, NULL, 1, 'mcq', 'សម្រួល \(\dfrac{(x-3)(x+3)}{x-3}=x+3\to6\) ដូច្នេះត្រូវកំណត់ \(g(3)=6\) ដើម្បីឱ្យបន្ថាយជាប់។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20505, 'ចន្លោះបិទធំបំផុតដែលអនុគមន៍ \(f(x)=\sqrt{4-x^2}\) ជាប់ គឺ ៖', NULL, '["\\([-2,2]\\)", "\\(\\mathbb{R}\\)", "\\((-2,2)\\)", "\\([0,2]\\)"]', 0, NULL, 1, 'mcq', 'ដែនកំណត់ \(4-x^2\ge0\) គឺ \(-2\le x\le2\) ហើយ \(f\) ជាប់ត្រង់ចុងទាំងពីរ (ខាងស្ដាំនៃ \(-2\) ខាងឆ្វេងនៃ \(2\))។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20506, 'គេមាន \(f(x)=|x|\)។ តើ \(f\) ជាប់ត្រង់ \(x=0\) ឬទេ ?', NULL, '["ជាប់ ព្រោះ \\(\\lim_{x\\to0}|x|=0=f(0)\\)", "ដាច់ ព្រោះ \\(\\lim_{x\\to0}f(x)\\ne f(0)\\)", "ដាច់ ព្រោះ \\(f(0)\\) មិនកំណត់", "ដាច់ ព្រោះលីមីតមិនមាន"]', 0, NULL, 1, 'mcq', '\(\lim_{x\to0^+}x=0\) និង \(\lim_{x\to0^-}(-x)=0\) ដូច្នេះ \(\lim_{x\to0}|x|=0=f(0)\) គឺ ជាប់។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20507, 'អនុគមន៍ \(f(x)=\dfrac{x + 1}{x - 4}\) ដាច់ត្រង់តម្លៃ \(x\) ណា ?', NULL, '["\\(x=-1\\)", "\\(x=0\\)", "\\(x=4\\)", "\\(x=-4\\)"]', 2, NULL, 1, 'mcq', 'អនុគមន៍សនិទានដាច់ត្រង់ចំណុចដែលភាគបែងសូន្យ ៖ \(x-4=0\) គឺ \(x=4\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20508, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} x + 3 & \text{បើ } x<1 \\ a x + 1 & \text{បើ } x\ge1 \end{cases}\) ជាប់ត្រង់ \(x=1\)។', NULL, '["\\(a=4\\)", "\\(a=2\\)", "\\(a=1\\)", "\\(a=3\\)"]', 3, NULL, 1, 'mcq', 'ខាងឆ្វេង ៖ \(1+3=4\) ; ខាងស្ដាំនិង \(f(1)\) ៖ \(a+1\) ។ ត្រូវ \(a+1=4\) គឺ \(a=3\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20509, 'អនុគមន៍ \(y=\tan x\) ដាច់ត្រង់តម្លៃមួយណាខាងក្រោម ?', NULL, '["\\(x=\\dfrac\\pi4\\)", "\\(x=\\dfrac\\pi2\\)", "\\(x=0\\)", "\\(x=\\pi\\)"]', 1, NULL, 1, 'mcq', '\(\tan x=\dfrac{\sin x}{\cos x}\) ហើយ \(\cos\dfrac\pi2=0\) ដូច្នេះមិនកំណត់ត្រង់ \(\dfrac\pi2\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20510, 'បើអនុគមន៍ \(f\) និង \(g\) ជាប់ត្រង់ \(x=c\) នោះ \(\dfrac{f(x)}{g(x)}\) ជាប់ត្រង់ \(x=c\) លុះត្រាតែ ៖', NULL, '["\\(g(c)\\ne0\\)", "\\(f(c)=g(c)\\)", "\\(f(c)\\ne0\\)", "\\(g(c)=0\\)"]', 0, NULL, 1, 'mcq', 'លក្ខណៈនៃភាពជាប់ ៖ ផលចែកជាប់ដរាបណាភាគបែង \(g(c)\ne0\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20511, 'អនុគមន៍ \(f(x)=\dfrac{x^2-4}{x^2-5x+6}\) ដាច់ត្រង់តម្លៃ \(x\) ណាខ្លះ ?', NULL, '["\\(x=-2\\) និង \\(x=2\\)", "\\(x=2\\) តែមួយ", "\\(x=3\\) តែមួយ", "\\(x=2\\) និង \\(x=3\\)"]', 3, NULL, 2, 'mcq', '\(x^2-5x+6=(x-2)(x-3)\) ដូច្នេះមិនកំណត់ត្រង់ \(2\) និង \(3\)។ (ត្រង់ \(2\) ដាច់ព្រោះមិនកំណត់ទោះមានលីមីត)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20512, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} x^{2} - 1 & \text{បើ } x<0 \\ a - x & \text{បើ } x\ge0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(a=1\\)", "\\(a=-2\\)", "\\(a=0\\)", "\\(a=-1\\)"]', 3, NULL, 2, 'mcq', 'ខាងឆ្វេង \(\to-1\) ; \(f(0)=a-0=a\) ។ ត្រូវ \(a=-1\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20513, 'គេមាន \(f(x)=\dfrac{x^2+x-6}{x-2}\) ដែល \(x\ne2\)។ អនុគមន៍បន្ថាយតាមភាពជាប់ត្រង់ \(x=2\) មានតម្លៃ \(g(2)\) ស្មើនឹងលីមីត \(\lim_{x\to 2}\dfrac{x^{2} + x - 6}{x - 2}\)។', NULL, '["\\(4\\)", "\\(6\\)", "\\(0\\)", "\\(5\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{(x+3)(x-2)}{x-2}=x+3\to5\) ដូច្នេះ \(g(2)=5\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20514, 'ចន្លោះណាខាងក្រោម ដែលអនុគមន៍ \(f(x)=\dfrac{x+3}{x-1}\) ជាប់ ?', NULL, '["\\((-\\infty,1]\\)", "\\((0,3)\\)", "\\((1,+\\infty)\\)", "\\([0,2]\\)"]', 2, NULL, 2, 'mcq', '\(f\) ជាអនុគមន៍សនិទាន មិនកំណត់ត្រង់ \(x=1\) ដូច្នេះជាប់លើ \((-\infty,1)\) និង \((1,+\infty)\) ។ ចន្លោះផ្សេងទៀតមានចំណុច \(1\)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20515, 'ចន្លោះណាមួយដែលប្រាកដថាមានឫសនៃសមីការ \(x^3-x-1=0\) ?', NULL, '["\\([0,1]\\)", "\\([-1,0]\\)", "\\([1,2]\\)", "\\([2,3]\\)"]', 2, NULL, 2, 'mcq', '\(f(1)=-1<0\) ហើយ \(f(2)=5>0\) ដូច្នេះមានឫសក្នុង \((1,2)\)។ ឯ \([-1,0]\), \([0,1]\) ទាំងពីរបាត់ជាអវិជ្ជមាន ហើយ \([2,3]\) ទាំងពីរវិជ្ជមាន។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20516, 'អនុគមន៍ \(f(x)=\dfrac{x-1}{x^2-1}\) ដាច់ត្រង់ចំនួនចំណុចប៉ុន្មាន ?', NULL, '["\\(2\\)", "\\(1\\)", "\\(0\\)", "\\(3\\)"]', 0, NULL, 2, 'mcq', '\(x^2-1=0\) គឺ \(x=\pm1\) ។ ចំណុចទាំងពីរ \(f\) មិនកំណត់ ដូច្នេះដាច់ត្រង់ \(2\) ចំណុច (ត្រង់ \(x=1\) ជាចំណុចដាច់អាចបន្ថាយបាន)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20517, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} a + 3 x & \text{បើ } x<2 \\ x^{2} - 1 & \text{បើ } x\ge2 \end{cases}\) ជាប់ចំពោះគ្រប់ចំនួនពិត \(x\)។', NULL, '["\\(a=3\\)", "\\(a=9\\)", "\\(a=-3\\)", "\\(a=-6\\)"]', 2, NULL, 2, 'mcq', 'ជាប់ត្រង់ \(x=2\) ៖ \(6+a=2^2-1=3\) គឺ \(a=-3\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20518, 'រកតម្លៃ \(k\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{\sin{\left(2 x \right)}}{x} & \text{បើ } x\ne0 \\ k & \text{បើ } x=0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(k=1\\)", "\\(k=2\\)", "\\(k=0\\)", "\\(k=\\dfrac12\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{\sin2x}{x}=2\cdot\dfrac{\sin2x}{2x}\to2\) ដូច្នេះត្រូវ \(k=2\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20519, 'អនុគមន៍ \(f(x)=\sqrt{\dfrac{x-1}{x+3}}\) ជាប់លើចន្លោះណា ?', NULL, '["\\((-\\infty,-3)\\cup[1,+\\infty)\\)", "\\((-3,1]\\)", "\\([1,+\\infty)\\)", "\\((-\\infty,-3]\\cup[1,+\\infty)\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{x-1}{x+3}\ge0\) គឺ \(x<-3\) ឬ \(x\ge1\) ហើយអនុគមន៍បណ្ដាក់ជាប់លើដែនកំណត់នេះ។ (\(x=-3\) មិនកំណត់)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20520, 'ចន្លោះណាមួយដែលសមីការ \(e^x+x=3\) ប្រាកដថាមានឫស ?', NULL, '["\\([0,1]\\)", "\\([1,2]\\)", "\\([2,3]\\)", "\\([-1,0]\\)"]', 0, NULL, 2, 'mcq', 'តាង \(f(x)=e^x+x-3\) ៖ \(f(0)=-2<0\) និង \(f(1)=e-2\approx0{,}72>0\)។ ឯចន្លោះផ្សេងមិនប្ដូរសញ្ញាទេ។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20521, 'រកតម្លៃ \(k\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{1 - \cos{\left(x \right)}}{x^{2}} & \text{បើ } x\ne0 \\ k & \text{បើ } x=0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(k=2\\)", "\\(k=0\\)", "\\(k=1\\)", "\\(k=\\dfrac12\\)"]', 3, NULL, 2, 'mcq', '\(1-\cos x=2\sin^2\tfrac x2\) ដូច្នេះ \(\dfrac{1-\cos x}{x^2}\to\dfrac12\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20522, 'អនុគមន៍មួយណាខាងក្រោម ជាប់ចំពោះគ្រប់ចំនួនពិត ?', NULL, '["\\(f(x)=\\tan x\\)", "\\(f(x)=\\sqrt{x-4}\\)", "\\(f(x)=|x^2-4|\\)", "\\(f(x)=\\dfrac{1}{x^2-4}\\)"]', 2, NULL, 2, 'mcq', '\(x^2-4\) ជាប់ ហើយ \(|\cdot|\) ជាប់ ដូច្នេះអនុគមន៍បណ្ដាក់ជាប់ \(\mathbb{R}\)។ ឯផ្សេងទៀតមិនកំណត់ត្រង់ចំណុចខ្លះ។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20523, 'សមីការ \(x^3+x=5\) មានឫសប៉ុន្មានក្នុងចន្លោះ \([1,2]\) ?', NULL, '["គ្មាន", "មួយ", "បី", "ពីរ"]', 1, NULL, 2, 'mcq', 'តាង \(f(x)=x^3+x\) ជាប់និងកើនដាច់ខាត \(f(1)=2<5<10=f(2)\) ដូច្នេះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាលនិងវិបាក មានឫសមួយគត់។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20524, 'គណនា \(\lim_{x\to 2}\sqrt{x^{2} + x - 1}\)។', NULL, '["\\(5\\)", "\\(\\sqrt{5}\\)", "\\(\\sqrt{3}\\)", "\\(2\\)"]', 1, NULL, 2, 'mcq', '\(x^2+x-1\to5\) ហើយ \(\sqrt\cdot\) ជាប់ត្រង់ \(5\) ដូច្នេះ \(\sqrt5\)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20525, 'រកតម្លៃ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} 2 x + 3 & \text{បើ } x<-1 \\ a x + b & \text{បើ } -1\le x\le2 \\ x^{2} & \text{បើ } x>2 \end{cases}\) ជាប់លើ \(\mathbb{R}\)។', NULL, '["\\(a=3,\\ b=0\\)", "\\(a=2,\\ b=1\\)", "\\(a=1,\\ b=3\\)", "\\(a=1,\\ b=2\\)"]', 3, NULL, 3, 'mcq', 'ត្រង់ \(x=-1\) ៖ \(2(-1)+3=1=-a+b\) ។ ត្រង់ \(x=2\) ៖ \(2a+b=2^2=4\)។ ដកគ្នា \(3a=3\) គឺ \(a=1\) ហើយ \(b=2\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20526, 'ចន្លោះណាមួយដែលសមីការ \(\cos x=x\) ប្រាកដថាមានឫស ?', NULL, '["\\([2,3]\\)", "\\([-2,-1]\\)", "\\([0,1]\\)", "\\([1,2]\\)"]', 2, NULL, 3, 'mcq', 'តាង \(f(x)=\cos x-x\) ៖ \(f(0)=1>0\) និង \(f(1)=\cos1-1\approx-0{,}46<0\)។ ឯ \([1,2]\), \([2,3]\) \(f\) អវិជ្ជមានទាំងពីរ ហើយ \([-2,-1]\) \(f\) វិជ្ជមានទាំងពីរ។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20527, 'កំណត់ \(g(0)\) ដែលធ្វើឱ្យ \(g(x)=\dfrac{\sqrt{1+x}-1}{x}\) ជាបន្ថាយជាប់ត្រង់ \(0\) ដោយគណនា \(\lim_{x\to 0}\dfrac{\sqrt{x + 1} - 1}{x}\)។', NULL, '["\\(2\\)", "\\(0\\)", "\\(\\dfrac{1}{2}\\)", "\\(1\\)"]', 2, NULL, 3, 'mcq', 'គុណអនុញ្ញាតិរួម ៖ \(\dfrac{x}{x(\sqrt{1+x}+1)}=\dfrac1{\sqrt{1+x}+1}\to\dfrac12\) ដូច្នេះ \(g(0)=\dfrac12\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20528, 'គេមាន \(f(x)=\begin{cases} x \sin{\left(\dfrac{1}{x} \right)} & \text{បើ } x\ne0 \\ 0 & \text{បើ } x=0 \end{cases}\)។ ការអះអាងមួយណាត្រឹមត្រូវ ?', NULL, '["\\(f\\) ដាច់ត្រង់ \\(0\\) ព្រោះ \\(f(0)\\) មិនកំណត់", "\\(f\\) ជាប់ត្រង់ \\(0\\) ព្រោះ \\(|x\\sin\\tfrac1x|\\le|x|\\to0=f(0)\\)", "\\(f\\) ដាច់ត្រង់ \\(0\\) ព្រោះ \\(\\sin\\tfrac1x\\) មិនមានលីមីត", "\\(f\\) ជាប់ត្រង់ \\(0\\) ព្រោះ \\(\\tfrac1x\\to\\infty\\)"]', 1, NULL, 3, 'mcq', 'ទ្រឹស្ដីបទកៀប ៖ \(-|x|\le x\sin\tfrac1x\le|x|\) ដូច្នេះលីមី \(=0=f(0)\) (ទោះ \(\sin\tfrac1x\) គ្មានលីមីត)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20529, 'ការអះអាងមួយណាត្រឹមត្រូវ ចំពោះ \(f(x)=\dfrac1x\) លើ \([-1,1]\) ?', NULL, '["មិនអាចប្រើទ្រឹស្ដីបទតម្លៃកណ្ដាលបាន ព្រោះ \\(f\\) មិនជាប់ត្រង់ \\(x=0\\)", "\\(f(c)=0\\) មានឫសពីរក្នុង \\((-1,1)\\)", "មាន \\(c\\in(-1,1)\\) ដែល \\(f(c)=0\\) ព្រោះ \\(f(-1)<0<f(1)\\)", "\\(f\\) ជាប់លើ \\([-1,1]\\) ព្រោះជាអនុគមន៍សនិទាន"]', 0, NULL, 3, 'mcq', '\(f(-1)=-1<0<1=f(1)\) តែ \(f\) មិនកំណត់ត្រង់ \(0\) ដូច្នេះលក្ខខណ្ឌ "ជាប់លើ \([-1,1]\)" មិនពិត ហើយ \(\dfrac1x\ne0\) គ្រប់ \(x\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20530, 'គេមាន \(f(x)=\begin{cases} \dfrac{a x + b + x^{2}}{x - 1} & \text{បើ } x\ne1 \\ 3 & \text{បើ } x=1 \end{cases}\) ជាប់ត្រង់ \(x=1\)។ តម្លៃ \(a+b\) ស្មើនឹង ៖', NULL, '["\\(1\\)", "\\(-1\\)", "\\(-3\\)", "\\(3\\)"]', 1, NULL, 3, 'mcq', 'ភាគយកត្រូវសូន្យត្រង់ \(1\) ៖ \(1+a+b=0\) គឺ \(a+b=-1\) (ហើយ \(\dfrac{(x-1)(x+1+a)}{x-1}\to2+a=3\) នាំឱ្យ \(a=1,\ b=-2\))។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20531, 'ដោយគណនា \(f(x)=x^3-3x+1\) ត្រង់ \(x=-2,-1,0,1,2\) តើទ្រឹស្ដីបទតម្លៃកណ្ដាលធានាបានថាសមីការ \(f(x)=0\) មានឫសយ៉ាងតិចប៉ុន្មាននៅក្នុង \((-2,2)\) ?', NULL, '["\\(3\\)", "\\(4\\)", "\\(1\\)", "\\(2\\)"]', 0, NULL, 3, 'mcq', '\(f(-2)=-1,\ f(-1)=3,\ f(0)=1,\ f(1)=-1,\ f(2)=3\) ។ សញ្ញាប្ដូរក្នុង \((-2,-1)\), \((0,1)\), \((1,2)\) ដូច្នេះមានឫសយ៉ាងតិច \(3\) (ហើយពហុធាដឺក្រេ \(3\) មិនលើស \(3\))។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-7c300c718d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20532, 'ក្រុមហ៊ុនអគ្គិសនីគិតថ្លៃ \(C(x)\) (ដុល្លារ) តាមអំពើប្រើ \(x\) kWh ដោយ \(C(x)=\begin{cases} \dfrac{3 x}{20} & \text{បើ } 0\le x\le200 \\ m + \dfrac{x}{10} - 20 & \text{បើ } x>200 \end{cases}\) ។ ដើម្បីកុំឱ្យក្រាបថ្លៃមានការលោត (ជាប់ត្រង់ \(x=200\)) ត្រូវយក \(m\) ស្មើនឹងប៉ុន្មាន ដូចក្នុងរូប ?', 'g12sc-7c300c718d.svg', '["\\(0{,}15\\)", "\\(15\\)", "\\(30\\)", "\\(20\\)"]', 2, NULL, 3, 'mcq', 'ជាប់ត្រង់ \(200\) ៖ \(m+0=0{,}15\times200=30\) ដូច្នេះ \(m=30\) ដុល្លារ។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-4ecfbfb04d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20533, 'សីតុណ្ហភាពក្នុងឡមួយ \(T(t)\) (°C) ក្រោយ \(t\) ម៉ោង ត្រូវបានកត់ត្រាដូចក្នុងរូប ។ ក្រាបមិនជាប់ត្រង់ \(t=4\)។ តើតម្លៃសីតុណ្ហភាព "លោត" ប៉ុន្មានដឺក្រេ ត្រង់ \(t=4\) ?', 'g12sc-4ecfbfb04d.svg', '["\\(5\\) °C", "\\(23\\) °C", "\\(4\\) °C", "\\(18\\) °C"]', 0, NULL, 3, 'mcq', 'ខាងឆ្វេង \(\lim_{t\to4^-}T=18\) ហើយ \(T(4)=\lim_{t\to4^+}T=23\) ដូច្នេះលោត \(23-18=5\) °C។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-1c1757519c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20534, 'អ្នកដើរភ្នំម្នាក់ចាប់ផ្ដើមនៅកម្ពស់ \(120\ \text{m}\) ហើយទៅដល់កម្ពស់ \(480\ \text{m}\) ក្រោយ \(6\) ម៉ោង តាមផ្លូវជាប់ ដូចក្នុងរូប ។ ហេតុអ្វីបានជាប្រាកដថាអ្នកដើរភ្នំនោះនៅកម្ពស់ \(300\ \text{m}\) យ៉ាងតិចម្ដង ?', 'g12sc-1c1757519c.svg', '["លីមីតអនន្ត ព្រោះគ្មានទីបញ្ចប់", "ទ្រឹស្ដីបទតម្លៃកណ្ដាល ព្រោះកម្ពស់ជាអនុគមន៍ជាប់នៃពេល", "ទ្រឹស្ដីបទពីតាគ័រ", "ទ្រឹស្ដីបទកៀប ព្រោះកម្ពស់ចងដោយតម្លៃពីរ"]', 1, NULL, 3, 'mcq', 'កម្ពស់ \(h(t)\) ជាអនុគមន៍ជាប់លើ \([0,6]\) និង \(h(0)=120<300<480=h(6)\) ដូច្នេះមាន \(t\in(0,6)\) ដែល \(h(t)=300\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-87d7694073.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20535, 'វិស្វករម្នាក់ដោះស្រាយ \(f(x)=x^3-2x-5=0\) ដោយដឹងថា \(f(2)=-1\) និង \(f(3)=16\) ដូចក្នុងរូប ។ ក្រោយគណនាចំណុចកណ្ដាល \(2{,}5\) ដែល \(f(2{,}5)\approx5{,}6>0\) តើឫសស្ថិតក្នុងចន្លោះណា ?', 'g12sc-87d7694073.svg', '["\\((0;\\ 2)\\)", "\\((3;\\ 4)\\)", "\\((2{,}5;\\ 3)\\)", "\\((2;\\ 2{,}5)\\)"]', 3, NULL, 3, 'mcq', '\(f(2)<0<f(2{,}5)\) ហើយ \(f\) ជាប់ ដូច្នេះឫសនៅក្នុង \((2;\ 2{,}5)\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-cdbeb7c56e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20536, 'ឧបករណ៍វាស់មួយបង្ហាញតម្លៃ \(R(t)=\dfrac{\sin t}{t}\) ចំពោះ \(t\ne0\) ហើយមិនមានតម្លៃត្រង់ \(t=0\) (រូបបង្ហាញក្រាបមានប្រហោង) ។ ដើម្បីឱ្យក្រាបជាប់ ត្រូវកំណត់ \(R(0)\) ស្មើនឹងប៉ុន្មាន ?', 'g12sc-cdbeb7c56e.svg', '["\\(\\pi\\)", "\\(0\\)", "\\(\\dfrac12\\)", "\\(1\\)"]', 3, NULL, 3, 'mcq', '\(\displaystyle\lim_{t\to0}\dfrac{\sin t}{t}=1\) ដូច្នេះត្រូវយក \(R(0)=1\) ដើម្បីបន្ថាយតាមភាពជាប់។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'pisa', 1, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20537, 'សិក្សាភាពជាប់ត្រង់ \(x=1\) នៃអនុគមន៍ \(f(x)=\begin{cases} 2 x - 1 & \text{បើ } x\le1 \\ x^{2} & \text{បើ } x>1 \end{cases}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌទី ១ ៖ \(f(1)=2(1)-1=1\) ដូច្នេះ \(f\) កំណត់ត្រង់ \(1\) (1 ពិន្ទុ)
លីមីតខាងឆ្វេង ៖ \(\displaystyle\lim_{x\to1^-}(2x-1)=1\) (1 ពិន្ទុ)
លីមីតខាងស្ដាំ ៖ \(\displaystyle\lim_{x\to1^+}x^2=1\) (1 ពិន្ទុ)
លីមីតទាំងពីរស្មើគ្នា ដូច្នេះ \(\displaystyle\lim_{x\to1}f(x)=1\) មាន (1 ពិន្ទុ)
\(\displaystyle\lim_{x\to1}f(x)=1=f(1)\) ដូច្នេះ \(f\) ជាប់ត្រង់ \(x=1\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20538, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{x^{2} - 5 x + 6}{x - 2} & \text{បើ } x\ne2 \\ a & \text{បើ } x=2 \end{cases}\) ជាប់ត្រង់ \(x=2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជាប់ត្រង់ \(2\) លុះត្រាតែ \(\displaystyle\lim_{x\to2}f(x)=f(2)=a\) (1 ពិន្ទុ)
ចំពោះ \(x\ne2\) ៖ \(x^2-5x+6=(x-2)(x-3)\) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{(x-2)(x-3)}{x-2}=x-3\) (1 ពិន្ទុ)
លីមីត ៖ \(\displaystyle\lim_{x\to2}(x-3)=-1\) (1 ពិន្ទុ)
ដូច្នេះ \(a=-1\) (ជាអនុគមន៍បន្ថាយជាប់នៃ \(x-3\))។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20539, 'កំណត់ចន្លោះដែលអនុគមន៍ \(f(x)=\sqrt{\dfrac{x-3}{x+2}}\) ជាប់ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដែនកំណត់ ៖ \(\dfrac{x-3}{x+2}\ge0\) និង \(x\ne-2\) (1 ពិន្ទុ)
តារាងសញ្ញា ៖ \(x-3\) សូន្យត្រង់ \(3\) ; \(x+2\) សូន្យត្រង់ \(-2\) (1 ពិន្ទុ)
ប្រភាគវិជ្ជមាន (ឬសូន្យ) កាលណា \(x<-2\) ឬ \(x\ge3\) (1 ពិន្ទុ)
ប្រភាគ \(\dfrac{x-3}{x+2}\) ជាប់ ហើយ \(\sqrt{\cdot}\) ជាប់ ដូច្នេះអនុគមន៍បណ្ដាក់ជាប់លើដែនកំណត់ (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ \(f\) ជាប់លើ \((-\infty,-2)\cup[3,+\infty)\) (ត្រង់ \(3\) ជាប់ខាងស្ដាំ)។ (1 ពិន្ទុ)', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20540, 'ក. បង្ហាញថាសមីការ \(x^3+x-1=0\) មានឫសក្នុងចន្លោះ \((0,1)\)។ ខ. បង្ហាញថាមានឫសតែមួយគត់ក្នុងចន្លោះនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(f(x)=x^3+x-1\) ជាអនុគមន៍ពហុធា ដូច្នេះជាប់លើ \([0,1]\) (1 ពិន្ទុ)
\(f(0)=-1<0\) និង \(f(1)=1+1-1=1>0\) (1 ពិន្ទុ)
ទ្រឹស្ដីបទតម្លៃកណ្ដាល ៖ មាន \(c\in(0,1)\) ដែល \(f(c)=0\) (1 ពិន្ទុ)
ខ. បើ \(0\le u<v\le1\) នោះ \(u^3<v^3\) និង \(u<v\) ដូច្នេះ \(f(u)<f(v)\) គឺ \(f\) កើនដាច់ខាត (1 ពិន្ទុ)
តាមវិបាក សមីការ \(f(x)=0\) មានចម្លើយតែមួយគត់ក្នុង \((0,1)\)។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20541, 'កំណត់ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{\sin{\left(3 x \right)}}{x} & \text{បើ } x<0 \\ a & \text{បើ } x=0 \\ \dfrac{e^{b x} - 1}{x} & \text{បើ } x>0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ខាងឆ្វេង ៖ \(\displaystyle\lim_{x\to0^-}\dfrac{\sin3x}{x}=3\lim\dfrac{\sin3x}{3x}=3\) (1 ពិន្ទុ)
ខាងស្ដាំ ៖ \(\displaystyle\lim_{x\to0^+}\dfrac{e^{bx}-1}{x}=b\lim\dfrac{e^{bx}-1}{bx}=b\) (បើ \(b\ne0\)) (1 ពិន្ទុ)
លក្ខខណ្ឌជាប់ ៖ \(3=f(0)=a=b\) (1 ពិន្ទុ)
ដូច្នេះ \(a=3\) និង \(b=3\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(b=0\) ឱ្យ \(f(x)=0\to0\ne3\) មិនបាន ដូច្នេះចម្លើយតែមួយគត់ \(a=b=3\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20542, 'កំណត់ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} 2 x + 3 & \text{បើ } x<-1 \\ a x + b & \text{បើ } -1\le x\le2 \\ x^{2} & \text{បើ } x>2 \end{cases}\) ជាប់ចំពោះគ្រប់ចំនួនពិត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពហុធានីមួយៗជាប់លើចន្លោះបើករបស់វា ដូច្នេះត្រូវពិនិត្យតែចំណុចភ្ជាប់ \(x=-1\) និង \(x=2\) (1 ពិន្ទុ)
ត្រង់ \(x=-1\) ៖ \(\displaystyle\lim_{x\to-1^-}(2x+3)=1\) និង \(f(-1)=-a+b\) (1 ពិន្ទុ)
សមីការទី ១ ៖ \(-a+b=1\) (1 ពិន្ទុ)
ត្រង់ \(x=2\) ៖ \(f(2)=2a+b\) និង \(\displaystyle\lim_{x\to2^+}x^2=4\) ដូច្នេះ \(2a+b=4\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធ ៖ ដកគ្នា \(3a=3\) ដូច្នេះ \(a=1\) ហើយ \(b=2\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-6ca596abe6.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20543, 'គេមាន \(f(x)=\begin{cases} x \sin{\left(\dfrac{1}{x} \right)} & \text{បើ } x\ne0 \\ 1 & \text{បើ } x=0 \end{cases}\) (រូបបង្ហាញក្រាបនៃ \(y=x\sin\tfrac1x\) ចន្លោះបន្ទាត់ \(y=\pm x\)) ។ ក. ប្រើទ្រឹស្ដីបទកៀបរក \(\displaystyle\lim_{x\to0}f(x)\) ។ ខ. តើ \(f\) ជាប់ត្រង់ \(0\) ឬទេ ? គ. ត្រូវកែ \(f(0)\) ជាប៉ុន្មានដើម្បីឱ្យជាប់ ?', 'g12sc-6ca596abe6.svg', '[]', 0, NULL, 5, 'writing', 'សម្រាប់ \(x\ne0\) ៖ \(-1\le\sin\tfrac1x\le1\) (1 ពិន្ទុ)
គុណនឹង \(|x|\) ៖ \(-|x|\le x\sin\tfrac1x\le|x|\) (ព្រោះ \(|x\sin\tfrac1x|\le|x|\)) (1 ពិន្ទុ)
ដោយ \(\displaystyle\lim_{x\to0}|x|=0\) តាមទ្រឹស្ដីបទកៀប \(\displaystyle\lim_{x\to0}x\sin\tfrac1x=0\) (1 ពិន្ទុ)
ខ. \(f(0)=1\ne0=\lim f(x)\) ដូច្នេះ \(f\) មិនជាប់ត្រង់ \(0\) (ដាច់អាចបន្ថាយបាន) (1 ពិន្ទុ)
គ. ត្រូវកែ \(f(0)=0\) ដើម្បីឱ្យ \(\lim_{x\to0}f(x)=f(0)\) ហើយ \(f\) ជាប់ត្រង់ \(0\)។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-26656a1871.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20544, 'ក្រាបនៃអនុគមន៍ជាប់ \(f:[0,1]\to[0,1]\) ត្រូវបានបង្ហាញក្នុងរូបជាមួយបន្ទាត់ \(y=x\) ។ បង្ហាញថាមាន \(c\in[0,1]\) ដែល \(f(c)=c\) (ចំណុចថេរ)។', 'g12sc-26656a1871.svg', '[]', 0, NULL, 5, 'writing', 'តាង \(g(x)=f(x)-x\) ជាប់លើ \([0,1]\) (ផលដកនៃអនុគមន៍ជាប់) (1 ពិន្ទុ)
ដោយ \(f(0)\in[0,1]\) នោះ \(g(0)=f(0)-0\ge0\) (1 ពិន្ទុ)
ដោយ \(f(1)\in[0,1]\) នោះ \(g(1)=f(1)-1\le0\) (1 ពិន្ទុ)
បើ \(g(0)=0\) ឬ \(g(1)=0\) នោះ \(c=0\) ឬ \(c=1\) ជាចំណុចថេរ (1 ពិន្ទុ)
បើមិនដូច្នេះ \(g(0)>0>g(1)\) តាមទ្រឹស្ដីបទតម្លៃកណ្ដាលមាន \(c\in(0,1)\) ដែល \(g(c)=0\) គឺ \(f(c)=c\)។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-a2179fe74c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20545, 'បង្ហាញថាសមីការ \(x^4-4x-1=0\) មានឫសពិតយ៉ាងតិចពីរ (ដូចរូប) ដោយប្រើទ្រឹស្ដីបទតម្លៃកណ្ដាល ហើយរកចន្លោះប្រវែង \(1\) ដែលមានឫសនីមួយៗ ។', 'g12sc-a2179fe74c.svg', '[]', 0, NULL, 5, 'writing', 'តាង \(f(x)=x^4-4x-1\) ជាពហុធា ដូច្នេះជាប់លើ \(\mathbb{R}\) (1 ពិន្ទុ)
គណនា ៖ \(f(-1)=1+4-1=4>0\) និង \(f(0)=-1<0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(-1)f(0)<0\) មានឫសមួយក្នុង \((-1,0)\) (1 ពិន្ទុ)
គណនា ៖ \(f(1)=1-4-1=-4<0\) និង \(f(2)=16-8-1=7>0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(1)f(2)<0\) មានឫសមួយទៀតក្នុង \((1,2)\) ហើយចន្លោះទាំងពីរមិនប៉ះគ្នា ដូច្នេះឫសខុសគ្នា។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-064b62794c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20546, 'ក្រុមហ៊ុនទូរសព្ទគិតថ្លៃ \(C(x)\) (ដុល្លារ) តាមបរិមាណទិន្នន័យ \(x\) GB ដោយ \(C(x)=\begin{cases} \dfrac{x}{4} & \text{បើ } 0\le x\le80 \\ m + \dfrac{3 x}{20} - 12 & \text{បើ } x>80 \end{cases}\) ដូចក្នុងរូប ។ ក. រក \(m\) ដើម្បីកុំឱ្យថ្លៃលោត ត្រង់ \(x=80\)។ ខ. គណនា \(C(200)\)។ គ. ប្រៀបធៀបថ្លៃមធ្យមក្នុង ១ GB ត្រង់ \(x=200\) និង \(x=80\)។', 'g12sc-064b62794c.svg', '[]', 0, NULL, 5, 'writing', 'ក. ជាប់ត្រង់ \(80\) ៖ \(\displaystyle\lim_{x\to80^-}C=\dfrac14\cdot80=20\) និង \(C(80^+)=m+0=m\) (1 ពិន្ទុ)
ដូច្នេះ \(m=20\) ដុល្លារ (1 ពិន្ទុ)
ខ. \(C(200)=20+0{,}15(200-80)=20+18=38\) ដុល្លារ (1 ពិន្ទុ)
គ. ថ្លៃមធ្យមត្រង់ \(80\) ៖ \(\dfrac{20}{80}=0{,}25\) ដុល្លារ/GB (1 ពិន្ទុ)
ត្រង់ \(200\) ៖ \(\dfrac{38}{200}=0{,}19\) ដុល្លារ/GB ទាបជាង ព្រោះអត្រាក្រោយ \(80\) ថោកជាង \(0{,}15<0{,}25\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-7cbbfa0a35.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20547, 'ចំណតរថយន្តគិតថ្លៃ \(P(t)\) (ដុល្លារ) ដោយ \(2\) ដុល្លារ សម្រាប់ម៉ោងទី ១ (\(0<t\le1\)) \(4\) ដុល្លារ សម្រាប់ \(1<t\le2\) \(6\) ដុល្លារ សម្រាប់ \(2<t\le3\) ដូចក្នុងរូប ។ ក. រក \(\displaystyle\lim_{t\to2^-}P(t)\) និង \(\displaystyle\lim_{t\to2^+}P(t)\) ។ ខ. តើ \(P\) ជាប់ត្រង់ \(t=2\) ឬទេ ? គ. តើ \(P\) ជាប់ខាងឆ្វេង ឬខាងស្ដាំត្រង់ \(t=2\) ?', 'g12sc-7cbbfa0a35.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(P(2)=4\) (ព្រោះ \(1<2\le2\)) \(\displaystyle\lim_{t\to2^-}P(t)=4\) (1 ពិន្ទុ)
\(\displaystyle\lim_{t\to2^+}P(t)=6\) (ព្រោះ \(2<t\le3\)) (1 ពិន្ទុ)
ខ. លីមីតខាងឆ្វេង \(4\ne6\) លីមីតខាងស្ដាំ ដូច្នេះ \(\lim_{t\to2}P(t)\) មិនមាន (1 ពិន្ទុ)
ដូច្នេះ \(P\) មិនជាប់ត្រង់ \(t=2\) (លោត \(6-4=2\) ដុល្លារ) (1 ពិន្ទុ)
គ. \(\lim_{t\to2^-}P=4=P(2)\) ដូច្នេះជាប់ខាងឆ្វេង ប៉ុន្តែមិនជាប់ខាងស្ដាំ។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-2e4030e1c2.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20548, 'សីតុណ្ហភាពបន្ទប់មួយ \(T(t)=-0{,}25(t-14)^2+27\) (°C) ចំពោះ \(6\le t\le14\) ដូចក្នុងរូប ។ ក. គណនា \(T(6)\) និង \(T(14)\)។ ខ. ពន្យល់ថាហេតុអ្វីមានពេលមួយដែល \(T=20\) °C ។ គ. រកពេលនោះ។', 'g12sc-2e4030e1c2.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(T(6)=-0{,}25(64)+27=11\) °C (1 ពិន្ទុ)
\(T(14)=-0{,}25(0)+27=27\) °C (1 ពិន្ទុ)
ខ. \(T\) ជាពហុធា ដូច្នេះជាប់លើ \([6,14]\) ហើយ \(T(6)=11<20<27=T(14)\) ដូច្នេះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាលមាន \(t\in(6,14)\) ដែល \(T(t)=20\) (1 ពិន្ទុ)
គ. \(-0{,}25(t-14)^2+27=20\) គឺ \((t-14)^2=28\) (1 ពិន្ទុ)
ដូច្នេះ \(t=14\pm2\sqrt7\) ; ដោយ \(t\le14\) បាន \(t=14-2\sqrt7\approx8{,}71\) ម៉ោង (ក្នុង \((6,14)\))។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20549, 'អ្នកគណនាចង់រកឫសនៃ \(f(x)=x^3-2x-5\) ដោយវិធីពុះពាក់កណ្ដាលចន្លោះ ចាប់ពី \([2,3]\) ដូចក្នុងរូប ។ ក. បង្ហាញថាមានឫសក្នុង \((2,3)\) ។ ខ. ធ្វើជំហានពុះបីដង រួចរកចន្លោះប្រវែង \(0{,}125\) ដែលមានឫស ។ គ. ពន្យល់ថាហេតុអ្វីត្រូវការភាពជាប់។', 'g12sc-87d7694073.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(f(2)=8-4-5=-1<0\) និង \(f(3)=27-6-5=16>0\) ហើយ \(f\) ជាប់ ដូច្នេះមានឫសក្នុង \((2,3)\) (1 ពិន្ទុ)
ខ. ជំហានទី ១ ៖ ចំណុចកណ្ដាល \(2{,}5\) \(f(2{,}5)=15{,}625-5-5=5{,}625>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}5)\) (1 ពិន្ទុ)
ជំហានទី ២ ៖ \(f(2{,}25)=11{,}390\,625-4{,}5-5=1{,}890\,625>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}25)\) (1 ពិន្ទុ)
ជំហានទី ៣ ៖ \(f(2{,}125)=9{,}595\,703-4{,}25-5=0{,}345\,703>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}125)\) ប្រវែង \(0{,}125\) (1 ពិន្ទុ)
គ. បើ \(f\) មិនជាប់ អាចលោតពីអវិជ្ជមានទៅវិជ្ជមានដោយមិនកាត់សូន្យ ដូច្នេះទ្រឹស្ដីបទតម្លៃកណ្ដាលមិនធានាឫស ; ឫសពិតប្រាកដ \(\approx2{,}0\,946\) នៅក្នុងចន្លោះចុងក្រោយ។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
