INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20550, 'ឧបករណ៍មួយបង្ហាញតម្លៃ \(f(t)=\dfrac{1-\cos t}{t^2}\) ចំពោះ \(t\ne0\) ដោយ \(f(0)\) មិនទាន់កំណត់ ដូចក្នុងរូប ។ បច្ចេកទេសករម្នាក់ឱ្យ \(f(0)=0\) ។ ក. រក \(\displaystyle\lim_{t\to0}f(t)\) ។ ខ. វាយតម្លៃថា \(f(0)=0\) ត្រឹមត្រូវឬទេ ។ គ. កំណត់អនុគមន៍បន្ថាយតាមភាពជាប់ត្រង់ \(t=0\)។', 'g12sc-7653bcae3e.svg', '[]', 0, NULL, 5, 'writing', 'ក. ប្រើ \(1-\cos t=2\sin^2\tfrac t2\) ៖ \(f(t)=\dfrac{2\sin^2\frac t2}{t^2}\) (1 ពិន្ទុ)
សរសេរ \(f(t)=\dfrac12\left(\dfrac{\sin\frac t2}{\frac t2}\right)^2\) (ព្រោះ \(\left(\tfrac t2\right)^2=\tfrac{t^2}4\) ហើយ \(2\cdot\tfrac14=\tfrac12\)) (1 ពិន្ទុ)
ប្រើ \(\displaystyle\lim_{u\to0}\dfrac{\sin u}{u}=1\) ជាមួយ \(u=\tfrac t2\) ៖ \(\displaystyle\lim_{t\to0}f(t)=\dfrac12\cdot1=\dfrac12\) (1 ពិន្ទុ)
ខ. \(f(0)=0\ne\dfrac12\) ដូច្នេះ \(f\) នឹងមិនជាប់ត្រង់ \(0\) (ក្រាបមានលោត) ដូច្នេះការកំណត់របស់បច្ចេកទេសករមិនត្រឹមត្រូវ (1 ពិន្ទុ)
គ. \(g(t)=\begin{cases}\dfrac{1-\cos t}{t^2}&t\ne0\\\dfrac12&t=0\end{cases}\) ជាអនុគមន៍ជាប់ត្រង់ \(0\)។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'pisa', 0, '12SC', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
